\documentclass[11pt]{amsart}
\usepackage{amsmath,amssymb,amsthm}
\usepackage[margin=1in]{geometry}
\usepackage{hyperref}

\theoremstyle{plain}
\newtheorem{theorem}{Theorem}
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{corollary}[theorem]{Corollary}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}

\newcommand{\oam}{\operatorname{oam}}
\newcommand{\lcm}{\operatorname{lcm}}
\newcommand{\C}{\mathbb{C}}
\newcommand{\R}{\mathbb{R}}
\newcommand{\Z}{\mathbb{Z}}

\title{The Topology of Knotted Light: A Contour-Integral Product Rule for Optical Charge}
\author{Aristotle}
\date{2026-07-14}

\begin{document}

\begin{abstract}
A laser beam carrying orbital angular momentum (OAM) --- ``knotted light'' --- is
characterized by an azimuthal phase factor $e^{i\ell\theta}$ whose integer $\ell$
is the \emph{topological charge} of the phase singularity threading the beam axis.
The charge is captured classically by the logarithmic-derivative contour integral
$w(\varphi) = \tfrac{1}{2\pi i}\oint \varphi'/\varphi\, d\theta$. Prior treatments
compute this only for the closed-form phase $e^{i\ell\theta}$ by unfolding the
exponential. We go deeper: we prove a general \emph{product rule for the winding
number}, $w(\varphi\cdot\psi) = w(\varphi) + w(\psi)$, directly from the contour
integral, for arbitrary differentiable, non-vanishing loops with continuous
logarithmic derivative. From this single structural law, additivity and
conservation of optical charge follow as genuine corollaries rather than as
artifacts of the exponential ansatz. We further show the winding number is
invariant under multiplication by any nonzero constant envelope, so the full
physical Laguerre--Gauss amplitude --- not merely its phase --- carries the same
integer charge. Finally we establish a bridge to number theory: for a coprime
$(p,q)$-torus-knot beam, the meridional charge $p\cdot q$ coincides with
$\lcm(p,q)$; the trefoil is the coprime pair $(2,3)$ with charge
$6 = \lcm(2,3)$. A purely topological invariant of knotted light thereby equals an
arithmetic invariant of its knot type.
\end{abstract}

\maketitle

\section{Introduction}

Light can be structured so that its wavefronts spiral about the propagation axis,
endowing the beam with orbital angular momentum. Along the axis of such a beam the
amplitude vanishes identically, producing a line of darkness --- a \emph{phase
singularity}. The phase circulates about this singularity, and the net
circulation over one turn is quantized to an integer $\ell$, the \emph{topological
charge}. This integrality underlies the practical appeal of ``knotted light'':
the charge is a discrete, robust label suitable for multiplexing optical
communication channels, for optical trapping, and for noise-resistant information
encoding.

The standard tool for extracting the charge is the winding-number contour integral
of complex analysis. Our aim is to establish additivity, conservation, and
envelope-invariance of optical charge as theorems flowing from a single structural
principle --- the product rule for the winding number --- proved directly at the
level of the contour integral, and then to exhibit an unexpected identity
connecting the charge of a torus-knot beam to the arithmetic of its knot
parameters.

The contributions are: (1) a general \emph{product rule}
$w(\varphi\psi) = w(\varphi) + w(\psi)$ (Section~\ref{sec:product}); (2)
\emph{envelope invariance} $w(c\varphi) = w(\varphi)$, whence the full
Laguerre--Gauss amplitude carries the phase's charge
(Section~\ref{sec:envelope}); (3) \emph{additivity and conservation} of optical
charge as corollaries (Section~\ref{sec:conservation}); and (4) a
\emph{topology/number-theory bridge}: for coprime $(p,q)$ the torus-knot beam
charge $p\cdot q$ equals $\lcm(p,q)$ (Section~\ref{sec:bridge}).

\section{Definitions}

Throughout, a \emph{loop} is a function $\varphi:\R\to\C$ considered over one full
azimuthal turn $\theta\in[0,2\pi]$; we write $\varphi'$ for its derivative.

\begin{definition}[OAM phase field]
For an integer charge $\ell$, the azimuthal phase field of an OAM beam is
\[
\oam_\ell(\theta) = e^{\,i\,\ell\,\theta} = \exp\!\big(\ell\,\theta\, i\big), \qquad \theta\in\R.
\]
\end{definition}

\begin{definition}[Physical beam amplitude]
The Laguerre--Gauss-like amplitude of radial order $|\ell|$ is
\[
A_\ell(r,\theta) = r^{\,|\ell|}\,\oam_\ell(\theta), \qquad r\ge 0.
\]
The factor $r^{|\ell|}$ forces $A_\ell(0,\theta)=0$ when $\ell\ne0$: the on-axis
phase singularity of knotted light.
\end{definition}

\begin{definition}[Winding number]
The winding number of a loop $\varphi$ is
\[
w(\varphi) = \frac{1}{2\pi i}\int_0^{2\pi}\frac{\varphi'(\theta)}{\varphi(\theta)}\,d\theta.
\]
\end{definition}

\begin{definition}[Torus-knot beam]
For integers $p,q$, the $(p,q)$-torus-knot beam is $T_{p,q}(\theta)=\oam_{pq}(\theta)$,
with meridional charge $w(T_{p,q})$. The trefoil is $T_{2,3}$.
\end{definition}

An \emph{admissible} loop is everywhere differentiable, nowhere zero, and has
continuous logarithmic derivative $\varphi'/\varphi$ on $[0,2\pi]$; admissibility
guarantees integrability of the integrand.

\section{The winding number of a pure OAM phase}

\begin{lemma}[Differentiability of the phase]\label{lem:deriv}
For every $\ell\in\Z$ and $\theta\in\R$, $\;\oam_\ell'(\theta)=i\,\ell\,\oam_\ell(\theta)$.
\end{lemma}
\begin{proof}[Proof sketch]
The inner map $\theta\mapsto\ell\theta i$ is real-linear with derivative $\ell i$;
composing with the entire exponential (its own derivative) via the chain rule
yields the factor $i\ell\,\oam_\ell(\theta)$.
\end{proof}

\begin{lemma}[Non-vanishing]\label{lem:nz}
$\oam_\ell(\theta)\ne0$ for all $\theta$, since the complex exponential never
vanishes.
\end{lemma}

\begin{theorem}[Topological charge $=$ winding number]\label{thm:charge}
For every integer $\ell$, $\;w(\oam_\ell)=\ell$.
\end{theorem}
\begin{proof}[Proof sketch]
By Lemmas~\ref{lem:deriv}--\ref{lem:nz} the integrand simplifies to the constant
$\oam_\ell'/\oam_\ell = i\ell$. Hence
$w(\oam_\ell)=\frac{1}{2\pi i}\int_0^{2\pi} i\ell\,d\theta
=\frac{1}{2\pi i}(2\pi)(i\ell)=\ell$.
\end{proof}

\section{The contour-integral product rule}\label{sec:product}

\begin{theorem}[Product rule]\label{thm:product}
Let $\varphi,\psi$ be admissible loops. Then
$w(\varphi\cdot\psi)=w(\varphi)+w(\psi)$.
\end{theorem}
\begin{proof}[Proof sketch]
By the Leibniz rule $(\varphi\psi)'=\varphi'\psi+\varphi\psi'$; dividing by
$\varphi\psi$ (both nowhere zero) gives the pointwise identity
\[
\frac{(\varphi\psi)'}{\varphi\psi}=\frac{\varphi'}{\varphi}+\frac{\psi'}{\psi}.
\]
Continuity of $\varphi'/\varphi$ and $\psi'/\psi$ makes each integrable on
$[0,2\pi]$, so the interval integral distributes over the sum; multiplying by
$\tfrac{1}{2\pi i}$ yields the claim.
\end{proof}

The hypotheses are load-bearing: continuity feeds integrability and non-vanishing
feeds the algebraic splitting.

\section{Envelope invariance and the physical amplitude}\label{sec:envelope}

\begin{theorem}[Constant-envelope invariance]\label{thm:smul}
For any nonzero constant $c\in\C$ and any loop $\varphi$, $\;w(c\,\varphi)=w(\varphi)$.
\end{theorem}
\begin{proof}[Proof sketch]
Under the convention that division by zero returns zero, the integrands agree
pointwise: $(c\varphi)'/(c\varphi)=\varphi'/\varphi$, the constant $c$ cancelling.
This requires neither differentiability nor non-vanishing of $\varphi$; only
$c\ne0$.
\end{proof}

\begin{theorem}[Charge of the full amplitude]\label{thm:beam}
For every integer $\ell$ and every radius $r>0$,
$\;w\big(\theta\mapsto A_\ell(r,\theta)\big)=\ell$.
\end{theorem}
\begin{proof}[Proof sketch]
Fix $r>0$. Then $A_\ell(r,\theta)=r^{|\ell|}\,\oam_\ell(\theta)$ with constant
prefactor $c=r^{|\ell|}>0$. Theorem~\ref{thm:smul} gives
$w(A_\ell(r,\cdot))=w(\oam_\ell)$, evaluated as $\ell$ by
Theorem~\ref{thm:charge}.
\end{proof}

The real, positive radial envelope contributes nothing to the winding number: the
integer charge is robust to the amplitude dressing of any physical optical system.

\section{Additivity and conservation of optical charge}\label{sec:conservation}

\begin{theorem}[Additivity via the product rule]\label{thm:add}
For integers $\ell,m$,
\[
w\big(\theta\mapsto\oam_\ell(\theta)\,\oam_m(\theta)\big)
= w(\oam_\ell)+w(\oam_m)=\ell+m.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Each OAM phase is admissible (Lemmas~\ref{lem:deriv}--\ref{lem:nz}, with constant
logarithmic derivative $i\ell$, resp.\ $im$). Theorem~\ref{thm:product} gives the
first equality; Theorem~\ref{thm:charge} evaluates each summand --- without
unfolding the exponential.
\end{proof}

\begin{theorem}[Conservation over a family]\label{thm:family}
For a finite family indexed by $s$ with charges $f(i)$,
\[
w\!\left(\theta\mapsto\prod_{i\in s}\oam_{f(i)}(\theta)\right)=\sum_{i\in s}f(i).
\]
\end{theorem}
\begin{proof}[Proof sketch]
The product of OAM phases is the OAM phase of the summed charge,
$\prod_i\oam_{f(i)}(\theta)=\oam_{\sum_i f(i)}(\theta)$; apply
Theorem~\ref{thm:charge} to $\sum_i f(i)$. Equivalently iterate
Theorem~\ref{thm:product}. Total optical charge is conserved.
\end{proof}

\section{A bridge to number theory: torus-knot beams}\label{sec:bridge}

\begin{theorem}[Torus-knot charge]\label{thm:torus}
For integers $p,q$, $\;w(T_{p,q})=p\cdot q$.
\end{theorem}
\begin{proof}[Proof sketch]
By definition $T_{p,q}=\oam_{pq}$; apply Theorem~\ref{thm:charge} with charge $pq$.
\end{proof}

\begin{theorem}[Topology $\leftrightarrow$ number theory]\label{thm:coprime}
For natural numbers $p,q\ge1$ with $\gcd(p,q)=1$, $\;w(T_{p,q})=\lcm(p,q)$.
\end{theorem}
\begin{proof}[Proof sketch]
When $\gcd(p,q)=1$ we have $\lcm(p,q)=p\cdot q$; combine with
Theorem~\ref{thm:torus}.
\end{proof}

\begin{corollary}[Trefoil]
The trefoil beam is $T_{2,3}$, and
$w(T_{2,3})=2\cdot3=6=\lcm(2,3)$.
\end{corollary}

The identity is sharp: coprimality is exactly the condition under which the torus
$(p,q)$ is a genuine (non-split, single-component) knot, and exactly the condition
under which $\lcm(p,q)=p\cdot q$. A topological invariant (a winding number) thus
coincides with an arithmetic invariant of the knot type.

\section{Discussion and future work}

Additivity and conservation of optical charge are properties of the logarithmic
derivative, not of the exponential ansatz: the winding number converts pointwise
multiplication of loops into addition of integers, so every admissible beam obeys
the same conservation law and the physical envelope is invisible to the charge.
Future directions include characterizing the winding number as a surjective group
homomorphism onto $(\Z,+)$ with kernel the loops admitting a single-valued
logarithm; promoting the coprimality/lcm identity to a count of connected
components of the singularity ($\gcd(p,q)$ components, knot vs.\ split link);
upgrading conservation to homotopy invariance in $\C\setminus\{0\}$; and proving
charge quantization survives arbitrary nowhere-zero, single-valued radial and
polarization dressings.

\section{Conclusion}

The topological charge of knotted light is an additive invariant governed by the
contour-integral product rule $w(\varphi\psi)=w(\varphi)+w(\psi)$, carried by the
full physical amplitude, conserved under superposition, and --- for torus-knot
beams --- equal to the arithmetic $\lcm$ of the knot parameters. The trefoil
$(2,3)$ realizes the smallest nontrivial instance, with charge $6=\lcm(2,3)$.
Optics, complex analysis, and number theory meet in a single integer.

